public class InstructionPcodeOverride : PcodeOverride {

	protected Instruction instr;

	private bool callOverrideApplied = false;
	private bool jumpOverrideApplied = false;
	private bool callOtherCallOverrideApplied = false;
	private bool callOtherJumpOverrideApplied = false;
	private Address primaryCallAddress = null;
	private List<Reference> primaryOverridingReferences;

	/**
	 * This constructor caches the primary and overriding "from" references of {@code instr}.  
	 * This cache is never updated; the assumption is that this object is short-lived 
	 * (duration of {@link PcodeEmit})  
	 * @param instr the instruction
	 */
	public InstructionPcodeOverride(Instruction instr) {
		this.instr = instr;
	}

	/**
	 * Initialize the cache or any references on an instruction that would cause an override.
	 * 
	 * @return list of any program overrides
	 */
	private List<Reference> getPrimaryOverridingReferences() {
		if (primaryOverridingReferences != null) {
			return primaryOverridingReferences;
		}
		
		primaryOverridingReferences = new();
		foreach (Reference @ref in instr.getReferencesFrom()) {
			if (!@ref.isPrimary() || !@ref.getToAddress().isMemoryAddress()) {
				continue;
			}
			RefType type = @ref.getReferenceType();
			if (type.isOverride()) {
				primaryOverridingReferences.add(@ref);
			}
			else if (type.isCall() && primaryCallAddress == null) {
				primaryCallAddress = @ref.getToAddress();
			}
		}
		
		return primaryOverridingReferences;
	}

	/* @Override */
	public Address getFallThroughOverride() {
		Address defaultFallAddr = instr.getDefaultFallThrough();
		Address fallAddr = instr.getFallThrough();
		if (fallAddr != null && (instr.isLengthOverridden() || !fallAddr.equals(defaultFallAddr))) {
			return fallAddr;
		}
		return null;
	}

	/* @Override */
	public FlowOverride getFlowOverride() {
		return instr.getFlowOverride();
	}

	/* @Override */
