	}

	/* @Override */
	public void setCallOtherJumpOverrideRefApplied() {
		callOtherJumpOverrideApplied = true;

	}

	/* @Override */
	public bool isCallOtherJumpOverrideApplied() {
		return callOtherJumpOverrideApplied;
	}

	/* @Override */
	public bool hasPotentialOverride() {
		List<Reference> overridingRefs = getPrimaryOverridingReferences();
		return !overridingRefs.isEmpty();
	}
